      "id": "49501620",
      "title": "Show HN: Cogram Studio – CAD and BIM workspace for humans and agents",
      "url": "https://studio.cogram.com/",
      "hnUrl": "https://news.ycombinator.com/item?id=49501620",
      "source": "Hacker News",
      "points": 6,
