      "id": "49504949",
      "title": "Which AI Do You Think Will Have the Greatest Impact on the World?",
      "url": "https://news.ycombinator.com/item?id=49504949",
      "hnUrl": "https://news.ycombinator.com/item?id=49504949",
      "source": "Hacker News",
